// Generated by QA Suite (testing-apis/openapi_tests.py). Same TC IDs as the compact test cases.
// Env: API_BASE_URL, API_TOKEN, API_TOKEN_OTHER (optional). Test accounts only.
import { test, expect } from '@playwright/test';
import { api, checkSchema } from './api-helpers';

test.describe("GET /accounts", () => {
  test("TC-001 GET /accounts geçerli istekle 200 döner ve yanıt şemaya uyar", { tag: ['@TC-001', '@api', '@smoke'] }, async ({ request }) => {
    const res = await api(request, "GET", "/accounts", {}, { body: null });
    expect(res.status()).toBe(200);
    expect(checkSchema(await res.json(), {"type": "array", "items": {"type": "object", "required": ["id", "iban", "currency", "balance"], "properties": {"id": {"type": "string"}, "iban": {"type": "string"}, "currency": {"type": "string", "enum": ["TRY", "EUR"]}, "balance": {"type": "number"}}}})).toEqual([]);
  });
  test("TC-002 GET /accounts kimlik bilgisi olmadan 401 döner", { tag: ['@TC-002', '@api', '@security'] }, async ({ request }) => {
    const res = await api(request, "GET", "/accounts", {}, { body: null, auth: false });
    expect(res.status()).toBe(401);
  });
  test("TC-003 GET /accounts 'Bearer' şeması olmayan Authorization başlığını 401 ile reddeder", { tag: ['@TC-003', '@api', '@security'] }, async ({ request }) => {
    const res = await api(request, "GET", "/accounts", {}, { body: null, auth: false, headers: { Authorization: process.env.API_TOKEN ?? '' } });
    expect(res.status()).toBe(401);
  });
});

test.describe("GET /accounts/{accountId}", () => {
  test("TC-004 GET /accounts/{accountId} geçerli istekle 200 döner ve yanıt şemaya uyar", { tag: ['@TC-004', '@api', '@smoke'] }, async ({ request }) => {
    const res = await api(request, "GET", "/accounts/{accountId}", {"accountId": "A-100"}, { body: null });
    expect(res.status()).toBe(200);
    expect(checkSchema(await res.json(), {"type": "object", "required": ["id", "iban", "currency", "balance"], "properties": {"id": {"type": "string"}, "iban": {"type": "string"}, "currency": {"type": "string", "enum": ["TRY", "EUR"]}, "balance": {"type": "number"}}})).toEqual([]);
  });
  test("TC-005 GET /accounts/{accountId} kimlik bilgisi olmadan 401 döner", { tag: ['@TC-005', '@api', '@security'] }, async ({ request }) => {
    const res = await api(request, "GET", "/accounts/{accountId}", {"accountId": "A-100"}, { body: null, auth: false });
    expect(res.status()).toBe(401);
  });
  test("TC-006 GET /accounts/{accountId} olmayan kaynak için 404 döner", { tag: ['@TC-006', '@api'] }, async ({ request }) => {
    const res = await api(request, "GET", "/accounts/{accountId}", {"accountId": "does-not-exist-000"}, { body: null });
    expect(res.status()).toBe(404);
  });
  test("TC-007 GET /accounts/{accountId} başka kullanıcının kaynağına erişimi reddeder (BOLA)", { tag: ['@TC-007', '@api', '@security'] }, async ({ request }) => {
    // A-100 belongs to API_TOKEN (alice), confirmed with GET /accounts; API_TOKEN_OTHER = bob.
    const res = await api(request, "GET", "/accounts/{accountId}", {"accountId": "A-100"}, { body: null, as: 'other' });
    const body = await res.text();
    expect([403, 404], body).toContain(res.status());
    expect(body).not.toContain('TR120006200000000000000100');
  });
});

