test.describe("GET /transfers/{transferId}", () => {
  test("TC-026 GET /transfers/{transferId} geçerli istekle 200 döner ve yanıt şemaya uyar", { tag: ['@TC-026', '@api', '@smoke'] }, async ({ request }) => {
    // Test data: the OpenAPI example T-1 does not exist in the environment, so create a 1 TRY transfer of API_TOKEN first.
    const created = await api(request, "POST", "/transfers", {}, { body: {"fromAccountId": "A-100", "toIban": "TR330006100519786457841326", "amount": 1, "currency": "TRY", "description": "TC-026"} });
    expect(created.ok(), await created.text()).toBe(true); // precondition only: 2xx (201 itself is checked by TC-008)
    const id = (await created.json()).id;
    const res = await api(request, "GET", "/transfers/{transferId}", {"transferId": id}, { body: null });
    expect(res.status()).toBe(200);
    expect(checkSchema(await res.json(), {"type": "object", "required": ["id", "status", "amount", "currency"], "properties": {"id": {"type": "string"}, "status": {"type": "string", "enum": ["COMPLETED", "PENDING", "REJECTED"]}, "amount": {"type": "number"}, "currency": {"type": "string"}, "fromAccountId": {"type": "string"}, "toIban": {"type": "string"}, "description": {"type": "string"}}})).toEqual([]);
  });
  test("TC-027 GET /transfers/{transferId} kimlik bilgisi olmadan 401 döner", { tag: ['@TC-027', '@api', '@security'] }, async ({ request }) => {
    const res = await api(request, "GET", "/transfers/{transferId}", {"transferId": "T-1"}, { body: null, auth: false });
    expect(res.status()).toBe(401);
  });
  test("TC-028 GET /transfers/{transferId} olmayan kaynak için 404 döner", { tag: ['@TC-028', '@api'] }, async ({ request }) => {
    const res = await api(request, "GET", "/transfers/{transferId}", {"transferId": "does-not-exist-000"}, { body: null });
    expect(res.status()).toBe(404);
  });
  test("TC-029 GET /transfers/{transferId} başka kullanıcının kaynağına erişimi reddeder (BOLA)", { tag: ['@TC-029', '@api', '@security'] }, async ({ request }) => {
    // Test data: create a transfer owned by API_TOKEN (alice, A-100), then request it as API_TOKEN_OTHER (bob).
    const created = await api(request, "POST", "/transfers", {}, { body: {"fromAccountId": "A-100", "toIban": "TR330006100519786457841326", "amount": 1, "currency": "TRY", "description": "TC-029"} });
    expect(created.ok(), await created.text()).toBe(true); // precondition only: 2xx (201 itself is checked by TC-008)
    const id = (await created.json()).id;
    const res = await api(request, "GET", "/transfers/{transferId}", {"transferId": id}, { body: null, as: 'other' });
    const body = await res.text();
    expect([403, 404], body).toContain(res.status());
    expect(body).not.toContain('TC-029');
  });
});

